-- After loading rows with explicit key values, move each identity sequence past
-- the highest existing value so that the next generated key does not collide.
-- START WITH LIMIT VALUE is supported for identity columns (12.1+).

ALTER TABLE categories      MODIFY (category_id   GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE suppliers       MODIFY (supplier_id   GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE products        MODIFY (product_id    GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE warehouses      MODIFY (warehouse_id  GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE employees       MODIFY (employee_id   GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE customers       MODIFY (customer_id   GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE addresses       MODIFY (address_id    GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE stock_movements MODIFY (movement_id   GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE carts           MODIFY (cart_id       GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE promotions      MODIFY (promotion_id  GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE coupons         MODIFY (coupon_id     GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE orders          MODIFY (order_id      GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE payments        MODIFY (payment_id    GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE shipments       MODIFY (shipment_id   GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE returns         MODIFY (return_id     GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE reviews         MODIFY (review_id     GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
